import { sql } from "drizzle-orm";
import {
  type AnyPgColumn,
  bigint,
  boolean,
  customType,
  date,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  primaryKey,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

/**
 * Conventions
 * - Primary keys are UUIDv7 generated by Postgres 18 (`uuidv7()`), so they sort by time.
 * - Money is `bigint` minor units (cents) + ISO currency code. Never floats.
 * - Every household-scoped table has `household_id` and is protected by row-level
 *   security (see drizzle/0001_rls.sql). The app role can only see rows whose
 *   household matches `current_setting('app.household_id')`.
 */

const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => "bytea",
});

const id = () => uuid().primaryKey().default(sql`uuidv7()`);
const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());
const money = () => bigint({ mode: "number" });
const householdId = () =>
  uuid()
    .notNull()
    .references(() => households.id, { onDelete: "cascade" });

// ───────────────────────────── Identity & auth (not household-scoped) ─────────────────────────────

export const users = pgTable("users", {
  id: id(),
  email: text().notNull().unique(),
  displayName: text().notNull(),
  /** Base64url WebAuthn user handle; random, never derived from email. */
  webauthnUserId: text().notNull().unique(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const passkeys = pgTable(
  "passkeys",
  {
    id: id(),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    credentialId: text().notNull().unique(),
    publicKey: bytea().notNull(),
    counter: bigint({ mode: "number" }).notNull().default(0),
    transports: text().array(),
    deviceType: text().notNull(),
    backedUp: boolean().notNull(),
    nickname: text().notNull().default("Passkey"),
    createdAt: createdAt(),
    lastUsedAt: timestamp({ withTimezone: true }),
  },
  (t) => [index().on(t.userId)],
);

export const totpSecrets = pgTable("totp_secrets", {
  userId: uuid()
    .primaryKey()
    .references(() => users.id, { onDelete: "cascade" }),
  /** Secret sealed with the server's auth key (see @mm/crypto). */
  secretSealed: text().notNull(),
  confirmedAt: timestamp({ withTimezone: true }),
  /** Last accepted time-step, to block code replay. */
  lastUsedStep: bigint({ mode: "number" }),
  createdAt: createdAt(),
});

export const recoveryCodes = pgTable(
  "recovery_codes",
  {
    id: id(),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    codeHash: text().notNull(),
    usedAt: timestamp({ withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index().on(t.userId)],
);

export const sessions = pgTable(
  "sessions",
  {
    /** SHA-256 of the session token; the raw token only lives in the cookie. */
    tokenHash: text().primaryKey(),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    householdId: uuid()
      .notNull()
      .references(() => households.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
    lastSeenAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp({ withTimezone: true }).notNull(),
    /** Time of last strong (passkey) authentication, for step-up checks. */
    authenticatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
    /** "passkey" | "recovery" | "demo". Recovery sessions can only add a passkey. */
    authMethod: text().notNull().default("passkey"),
    userAgent: text(),
    ip: text(),
  },
  (t) => [index().on(t.userId), index().on(t.expiresAt), index().on(t.householdId)],
);

/** Short-lived WebAuthn challenges, bound to an opaque cookie value. */
export const authChallenges = pgTable("auth_challenges", {
  id: text().primaryKey(),
  challenge: text().notNull(),
  purpose: text().notNull(),
  userId: uuid(),
  payload: jsonb(),
  expiresAt: timestamp({ withTimezone: true }).notNull(),
});

/** Instance-wide key/value settings (e.g. hashed first-run setup token). */
export const appSettings = pgTable("app_settings", {
  key: text().primaryKey(),
  value: jsonb().notNull(),
  updatedAt: updatedAt(),
});

// ───────────────────────────── Households ─────────────────────────────

export const memberRole = pgEnum("member_role", ["owner", "member", "viewer"]);

export const budgetMode = pgEnum("budget_mode", ["flexible", "zero_based"]);

export const households = pgTable("households", {
  id: id(),
  name: text().notNull(),
  currency: text().notNull().default("USD"),
  /** flexible: budget what you like. zero_based: every dollar of income gets a job. */
  budgetMode: budgetMode().notNull().default("flexible"),
  /** Alert settings: ntfy endpoint and thresholds. See apps/worker/src/jobs/alerts.ts. */
  notifications: jsonb().notNull().default(sql`'{}'::jsonb`),
  /** Opt-in AI features: { enabled, categorize, digest }. Off unless an owner turns it on. */
  ai: jsonb().notNull().default(sql`'{}'::jsonb`),
  /** Card rewards settings: { valuation: "typical" | "floor", cpp: { [program]: cents } }. */
  rewards: jsonb().notNull().default(sql`'{}'::jsonb`),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const householdMembers = pgTable(
  "household_members",
  {
    householdId: householdId(),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    role: memberRole().notNull().default("member"),
    createdAt: createdAt(),
  },
  (t) => [primaryKey({ columns: [t.householdId, t.userId] }), index().on(t.userId)],
);

export const invites = pgTable(
  "invites",
  {
    id: id(),
    householdId: householdId(),
    email: text().notNull(),
    role: memberRole().notNull().default("member"),
    tokenHash: text().notNull().unique(),
    invitedBy: uuid().references(() => users.id, { onDelete: "set null" }),
    expiresAt: timestamp({ withTimezone: true }).notNull(),
    acceptedAt: timestamp({ withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index().on(t.householdId)],
);

// ───────────────────────────── Connections & accounts ─────────────────────────────

export const connectionProvider = pgEnum("connection_provider", [
  "manual",
  "file",
  "simplefin",
  "plaid",
  "teller",
]);
export const connectionStatus = pgEnum("connection_status", [
  "linking",
  "active",
  "needs_reauth",
  "error",
  "disconnected",
]);

export const connections = pgTable(
  "connections",
  {
    id: id(),
    householdId: householdId(),
    provider: connectionProvider().notNull(),
    institutionName: text().notNull(),
    institutionId: text(),
    /**
     * Aggregator access token/URL, sealed to the worker's public key. The web tier
     * can write this column but cannot decrypt it.
     */
    secretSealed: text(),
    /** Provider sync cursor (e.g. Plaid /transactions/sync cursor). */
    cursor: text(),
    status: connectionStatus().notNull().default("active"),
    lastSyncedAt: timestamp({ withTimezone: true }),
    nextSyncAt: timestamp({ withTimezone: true }),
    lastError: text(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index().on(t.householdId), index().on(t.nextSyncAt)],
);

export const accountType = pgEnum("account_type", [
  "depository",
  "credit",
  "loan",
  "investment",
  "property",
  "other",
]);

export const accounts = pgTable(
  "accounts",
  {
    id: id(),
    householdId: householdId(),
    connectionId: uuid().references(() => connections.id, { onDelete: "set null" }),
    providerAccountId: text(),
    name: text().notNull(),
    officialName: text(),
    type: accountType().notNull(),
    subtype: text(),
    /** Last 2–4 digits only. Full account numbers are never stored. */
    mask: text(),
    currency: text().notNull().default("USD"),
    currentBalance: money().notNull().default(0),
    availableBalance: money(),
    creditLimit: money(),
    balanceUpdatedAt: timestamp({ withTimezone: true }),
    hidden: boolean().notNull().default(false),
    includeInNetWorth: boolean().notNull().default(true),
    sortOrder: integer().notNull().default(0),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index().on(t.householdId), uniqueIndex().on(t.connectionId, t.providerAccountId)],
);

export const balanceSnapshots = pgTable(
  "balance_snapshots",
  {
    householdId: householdId(),
    accountId: uuid()
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    date: date({ mode: "string" }).notNull(),
    balance: money().notNull(),
  },
  (t) => [primaryKey({ columns: [t.accountId, t.date] }), index().on(t.householdId, t.date)],
);

// ───────────────────────────── Categorization ─────────────────────────────

export const categoryKind = pgEnum("category_kind", ["income", "expense", "transfer"]);

export const categoryGroups = pgTable(
  "category_groups",
  {
    id: id(),
    householdId: householdId(),
    name: text().notNull(),
    kind: categoryKind().notNull(),
    sortOrder: integer().notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [index().on(t.householdId)],
);

export const categories = pgTable(
  "categories",
  {
    id: id(),
    householdId: householdId(),
    groupId: uuid()
      .notNull()
      .references(() => categoryGroups.id, { onDelete: "cascade" }),
    name: text().notNull(),
    icon: text(),
    hidden: boolean().notNull().default(false),
    /** Unspent (or overspent) budget carries into the next month. */
    rollover: boolean().notNull().default(false),
    sortOrder: integer().notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [
    index().on(t.householdId),
    uniqueIndex().on(t.householdId, t.name),
    index().on(t.groupId),
  ],
);

export const merchants = pgTable(
  "merchants",
  {
    id: id(),
    householdId: householdId(),
    name: text().notNull(),
    defaultCategoryId: uuid().references(() => categories.id, { onDelete: "set null" }),
    logoUrl: text(),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex().on(t.householdId, t.name), index().on(t.defaultCategoryId)],
);

export const tags = pgTable(
  "tags",
  {
    id: id(),
    householdId: householdId(),
    name: text().notNull(),
    color: text(),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex().on(t.householdId, t.name)],
);

// ───────────────────────────── Transactions ─────────────────────────────

/** One file import. Its rows carry its id, so an import into the wrong account can be undone. */
export const imports = pgTable(
  "imports",
  {
    id: id(),
    householdId: householdId(),
    accountId: uuid()
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    fileName: text(),
    createdBy: uuid().references(() => users.id, { onDelete: "set null" }),
    /** Rows this import added (rows that were already there are not part of it). */
    added: integer().notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [index().on(t.householdId, t.createdAt), index().on(t.accountId)],
);

export const transactions = pgTable(
  "transactions",
  {
    id: id(),
    householdId: householdId(),
    accountId: uuid()
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    providerTransactionId: text(),
    date: date({ mode: "string" }).notNull(),
    /** Positive = money in, negative = money out (from the account's perspective). */
    amount: money().notNull(),
    currency: text().notNull().default("USD"),
    pending: boolean().notNull().default(false),
    rawDescription: text().notNull(),
    merchantId: uuid().references(() => merchants.id, { onDelete: "set null" }),
    categoryId: uuid().references(() => categories.id, { onDelete: "set null" }),
    notes: text(),
    excluded: boolean().notNull().default(false),
    reviewed: boolean().notNull().default(false),
    /** Set on the parts of a split. Parts go when their parent goes. */
    splitParentId: uuid().references((): AnyPgColumn => transactions.id, { onDelete: "cascade" }),
    /** True on a parent whose amount is divided among child rows; aggregates use the children. */
    isSplit: boolean().notNull().default(false),
    /** Who set the category: "rule", "merchant", "ai" or "user". Null when uncategorized or unknown. */
    categorySource: text(),
    /** Provider's category hint (Plaid personal_finance_category.detailed); used for rewards. */
    providerCategory: text(),
    /** The file import that added this row, if one did. */
    importId: uuid().references(() => imports.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index().on(t.householdId, t.date),
    index().on(t.accountId, t.date),
    index().on(t.categoryId),
    index().on(t.merchantId),
    index().on(t.splitParentId),
    index().on(t.importId),
    uniqueIndex().on(t.accountId, t.providerTransactionId),
  ],
);

export const transactionTags = pgTable(
  "transaction_tags",
  {
    householdId: householdId(),
    transactionId: uuid()
      .notNull()
      .references(() => transactions.id, { onDelete: "cascade" }),
    tagId: uuid()
      .notNull()
      .references(() => tags.id, { onDelete: "cascade" }),
  },
  (t) => [
    primaryKey({ columns: [t.transactionId, t.tagId] }),
    index().on(t.tagId),
    index().on(t.householdId),
  ],
);

export const rules = pgTable(
  "rules",
  {
    id: id(),
    householdId: householdId(),
    name: text().notNull(),
    /** e.g. [{ field: "description", op: "contains", value: "STARBUCKS" }] */
    conditions: jsonb().notNull(),
    /** e.g. { setCategoryId, setMerchantName, addTagIds, markReviewed } */
    actions: jsonb().notNull(),
    priority: integer().notNull().default(0),
    enabled: boolean().notNull().default(true),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index().on(t.householdId)],
);

// ───────────────────────────── Planning ─────────────────────────────

/** Amount budgeted for one category in one month (month = first day of the month). */
export const budgetItems = pgTable(
  "budget_items",
  {
    id: id(),
    householdId: householdId(),
    categoryId: uuid()
      .notNull()
      .references(() => categories.id, { onDelete: "cascade" }),
    month: date({ mode: "string" }).notNull(),
    /** Positive minor units. */
    amount: money().notNull(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex().on(t.categoryId, t.month), index().on(t.householdId, t.month)],
);

/** Detected subscriptions, bills and regular income. Re-detected after each sync. */
export const recurringSeries = pgTable(
  "recurring_series",
  {
    id: id(),
    householdId: householdId(),
    merchantId: uuid()
      .notNull()
      .references(() => merchants.id, { onDelete: "cascade" }),
    /** "in" for income, "out" for bills/subscriptions. */
    direction: text().notNull(),
    cadence: text().notNull(),
    intervalDays: integer().notNull(),
    /** Typical signed amount (minor units). */
    expectedAmount: money().notNull(),
    lastAmount: money().notNull(),
    lastDate: date({ mode: "string" }).notNull(),
    nextDate: date({ mode: "string" }).notNull(),
    occurrences: integer().notNull(),
    categoryId: uuid().references(() => categories.id, { onDelete: "set null" }),
    /** Signed change of the latest charge vs. the typical amount, when notable. */
    priceChange: money(),
    /** active | dismissed (user said "not recurring"). */
    status: text().notNull().default("active"),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex().on(t.merchantId, t.direction),
    index().on(t.householdId, t.nextDate),
    index().on(t.categoryId),
  ],
);

export const goals = pgTable(
  "goals",
  {
    id: id(),
    householdId: householdId(),
    name: text().notNull(),
    icon: text(),
    targetAmount: money().notNull(),
    targetDate: date({ mode: "string" }),
    /** Progress = sum of these accounts' balances; empty means use manualAmount. */
    accountIds: uuid().array().notNull().default(sql`'{}'::uuid[]`),
    manualAmount: money().notNull().default(0),
    archived: boolean().notNull().default(false),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index().on(t.householdId)],
);

// ───────────────────────────── Investments ─────────────────────────────

export const securities = pgTable(
  "securities",
  {
    id: id(),
    householdId: householdId(),
    /** Provider id (e.g. Plaid security_id), or "manual:<SYMBOL>" for user-entered holdings. */
    providerSecurityId: text().notNull(),
    symbol: text(),
    name: text().notNull(),
    /** equity | etf | mutual fund | fixed income | cash | cryptocurrency | derivative | other */
    type: text(),
    currency: text().notNull().default("USD"),
    /** Last known price per unit, as an exact decimal string. */
    price: numeric({ precision: 24, scale: 8 }),
    priceAsOf: date({ mode: "string" }),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex().on(t.householdId, t.providerSecurityId)],
);

export const holdings = pgTable(
  "holdings",
  {
    id: id(),
    householdId: householdId(),
    accountId: uuid()
      .notNull()
      .references(() => accounts.id, { onDelete: "cascade" }),
    securityId: uuid()
      .notNull()
      .references(() => securities.id, { onDelete: "cascade" }),
    quantity: numeric({ precision: 28, scale: 10 }).notNull(),
    /** Market value in minor units. */
    value: money().notNull(),
    /** Total cost basis in minor units, when known. */
    costBasis: money(),
    asOf: date({ mode: "string" }).notNull(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex().on(t.accountId, t.securityId),
    index().on(t.householdId),
    index().on(t.securityId),
  ],
);

// ───────────────────────────── Intelligence ─────────────────────────────

/** Generated insights such as the weekly digest. */
export const insights = pgTable(
  "insights",
  {
    id: id(),
    householdId: householdId(),
    kind: text().notNull(),
    periodStart: date({ mode: "string" }).notNull(),
    title: text().notNull(),
    /** { summary, highlights: string[], anomalies: [...] } */
    body: jsonb().notNull(),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex().on(t.householdId, t.kind, t.periodStart)],
);

/** Token usage of every AI call, shown to the household for transparency. */
export const aiUsage = pgTable(
  "ai_usage",
  {
    id: id(),
    householdId: householdId(),
    feature: text().notNull(),
    model: text().notNull(),
    inputTokens: integer().notNull(),
    outputTokens: integer().notNull(),
    createdAt: createdAt(),
  },
  (t) => [index().on(t.householdId, t.createdAt)],
);

/** De-duplicates alerts: one row per (kind, key) ever sent. */
export const notificationLog = pgTable(
  "notification_log",
  {
    id: id(),
    householdId: householdId(),
    kind: text().notNull(),
    key: text().notNull(),
    sentAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex().on(t.householdId, t.kind, t.key)],
);

// ───────────────────────────── Operations ─────────────────────────────

export const syncRuns = pgTable(
  "sync_runs",
  {
    id: id(),
    householdId: householdId(),
    connectionId: uuid()
      .notNull()
      .references(() => connections.id, { onDelete: "cascade" }),
    startedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
    finishedAt: timestamp({ withTimezone: true }),
    status: text().notNull().default("running"),
    added: integer().notNull().default(0),
    modified: integer().notNull().default(0),
    removed: integer().notNull().default(0),
    error: text(),
  },
  (t) => [index().on(t.connectionId, t.startedAt), index().on(t.householdId, t.startedAt)],
);

export const auditLog = pgTable(
  "audit_log",
  {
    id: id(),
    /** Null for instance-level events (e.g. failed login before a household is known). */
    householdId: uuid().references(() => households.id, { onDelete: "cascade" }),
    userId: uuid().references(() => users.id, { onDelete: "set null" }),
    action: text().notNull(),
    detail: jsonb(),
    ip: text(),
    userAgent: text(),
    createdAt: createdAt(),
  },
  (t) => [index().on(t.householdId, t.createdAt), index().on(t.userId)],
);

// ───────────────────────────── Agent access ─────────────────────────────

/**
 * Bearer tokens for the MCP server (Settings → Agents). Only the SHA-256 hash is stored.
 * A token acts as `user_id`, capped at `max_role` and its scopes; see @mm/services tokens.ts.
 */
export const apiTokens = pgTable(
  "api_tokens",
  {
    id: id(),
    householdId: householdId(),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    name: text().notNull(),
    tokenHash: text().notNull().unique(),
    /** First characters of the token, shown so people can tell tokens apart. */
    prefix: text().notNull(),
    scopes: text().array().notNull(),
    maxRole: memberRole().notNull(),
    expiresAt: timestamp({ withTimezone: true }).notNull(),
    lastUsedAt: timestamp({ withTimezone: true }),
    lastUsedIp: text(),
    revokedAt: timestamp({ withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index().on(t.householdId), index().on(t.userId)],
);

// ───────────────────────────── Card rewards ─────────────────────────────
// The card and program catalog ships as data in @mm/rewards; earnings are computed on read
// (@mm/services rewards.ts). These tables hold only the household's own choices.

/** A credit card account linked to a catalog card. */
export const walletCards = pgTable(
  "wallet_cards",
  {
    id: id(),
    householdId: householdId(),
    accountId: uuid()
      .notNull()
      .unique()
      .references(() => accounts.id, { onDelete: "cascade" }),
    /** Catalog card slug (@mm/rewards). */
    cardSlug: text().notNull(),
    /** For cardmember-year caps. */
    openedOn: date({ mode: "string" }),
    /** Rotating-category quarters the cardholder activated, e.g. {"2026-Q4"}. */
    activations: text().array().notNull().default(sql`'{}'::text[]`),
    /** Reward categories chosen for "user_choice" rates. */
    choices: text().array().notNull().default(sql`'{}'::text[]`),
    /** Sign-up bonus being worked on: { points, minSpend (dollars), deadline, startDate? }. */
    signupBonus: jsonb(),
    /** Statement credits the household actually uses per year, in cents (for fee value). */
    creditsValue: money().notNull().default(0),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index().on(t.householdId)],
);

/** Budget category → reward category, overriding the defaults in @mm/rewards. */
export const rewardCategoryMap = pgTable(
  "reward_category_map",
  {
    householdId: householdId(),
    categoryId: uuid()
      .primaryKey()
      .references(() => categories.id, { onDelete: "cascade" }),
    rewardCategory: text().notNull(),
  },
  (t) => [index().on(t.householdId)],
);

/** Merchant → reward category (e.g. Costco → wholesale_clubs), ahead of the category map. */
export const merchantRewardCategories = pgTable(
  "merchant_reward_categories",
  {
    householdId: householdId(),
    merchantId: uuid()
      .primaryKey()
      .references(() => merchants.id, { onDelete: "cascade" }),
    rewardCategory: text().notNull(),
  },
  (t) => [index().on(t.householdId)],
);

/** Points and miles balances by program, entered by a person or an agent (aggregators don't report them). */
export const pointsBalances = pgTable(
  "points_balances",
  {
    householdId: householdId(),
    /** Program slug (@mm/rewards). */
    programSlug: text().notNull(),
    balance: bigint({ mode: "number" }).notNull(),
    asOf: date({ mode: "string" }).notNull(),
    updatedAt: updatedAt(),
  },
  (t) => [primaryKey({ columns: [t.householdId, t.programSlug] })],
);

/**
 * The household's edits to the shipped card catalog (@mm/rewards): a patch of top-level
 * fields per card or program, or a whole card for cards the catalog doesn't have
 * (`custom`). The effective catalog is the shipped one with these applied, so app upgrades
 * refresh the defaults and these keep winning until reset.
 */
export const catalogOverrides = pgTable(
  "catalog_overrides",
  {
    householdId: householdId(),
    entity: text({ enum: ["card", "program"] }).notNull(),
    slug: text().notNull(),
    patch: jsonb().notNull(),
    custom: boolean().notNull().default(false),
    updatedAt: updatedAt(),
  },
  (t) => [primaryKey({ columns: [t.householdId, t.entity, t.slug] })],
);

/**
 * Append-only history of catalog edits, for review and revert. `before` and `after` are the
 * override patch (null = no override). Pending rows are proposals waiting for approval.
 */
export const catalogChanges = pgTable(
  "catalog_changes",
  {
    id: id(),
    householdId: householdId(),
    entity: text({ enum: ["card", "program"] }).notNull(),
    slug: text().notNull(),
    action: text({ enum: ["update", "add", "reset", "revert"] }).notNull(),
    status: text({ enum: ["applied", "pending", "rejected", "reverted"] }).notNull(),
    before: jsonb(),
    after: jsonb(),
    /** Whether the entry is a household-only card (not in the shipped catalog). */
    custom: boolean().notNull().default(false),
    sourceUrl: text(),
    asOf: date({ mode: "string" }),
    note: text(),
    userId: uuid().references(() => users.id, { onDelete: "set null" }),
    via: text({ enum: ["session", "token", "worker"] }).notNull(),
    tokenId: uuid(),
    /** For a revert: the change it undid. */
    revertsId: uuid(),
    decidedBy: uuid().references(() => users.id, { onDelete: "set null" }),
    decidedAt: timestamp({ withTimezone: true }),
    createdAt: createdAt(),
  },
  (t) => [index().on(t.householdId, t.createdAt), index().on(t.householdId, t.entity, t.slug)],
);

/** One transaction's reward category, ahead of everything else (e.g. a portal booking). */
export const transactionRewardOverrides = pgTable(
  "transaction_reward_overrides",
  {
    householdId: householdId(),
    transactionId: uuid()
      .primaryKey()
      .references(() => transactions.id, { onDelete: "cascade" }),
    rewardCategory: text().notNull(),
  },
  (t) => [index().on(t.householdId)],
);

/**
 * Tables protected by household row-level security. rls.test.ts compares this list with the
 * policies in the migrated database, so a table missing here or missing a policy fails CI.
 */
export const HOUSEHOLD_SCOPED_TABLES = [
  "invites",
  "connections",
  "accounts",
  "balance_snapshots",
  "category_groups",
  "categories",
  "merchants",
  "tags",
  "transactions",
  "transaction_tags",
  "rules",
  "sync_runs",
  "budget_items",
  "recurring_series",
  "goals",
  "securities",
  "holdings",
  "notification_log",
  "insights",
  "ai_usage",
  "api_tokens",
  "wallet_cards",
  "reward_category_map",
  "merchant_reward_categories",
  "transaction_reward_overrides",
  "points_balances",
  "catalog_overrides",
  "catalog_changes",
  "imports",
] as const;
